const int LANES = 16;
load_b_rows: for (int j = 0; j < J; ++j) {
  load_b_chunks: for (int k0 = 0; k0 < K; k0 += LANES) {
#pragma HLS PIPELINE II=1
    load_b_lanes: for (int u = 0; u < LANES; ++u) {
#pragma HLS UNROLL
      B_local[j][k0 + u] = B[j][k0 + u];
    }
  }
}
// Tile A the same way: outer i < TI, inner k0 += LANES. Never for (k=0;k<K;++k) B_local[j][k]=B[j][k];

// If flash had dot64 + compute_i/compute_j, keep it on the tile:
compute_tile_rows: for (int i = 0; i < TI; ++i) {
  compute_tile_cols: for (int j = 0; j < J; ++j) {
#pragma HLS PIPELINE II=1
    C_buf[i][j] = dot64(A_buf[i], B_local[j]);
  }
}
// If flash already had PE/SIMD, copy that nest and only limit i0 to the tile.

load_B(B, B_local); // flash LANES=16 body
tile_loop: for (int t = 0; t < NT; ++t) {
#pragma HLS DATAFLOW
  data_t A_buf[TI][K];
  data_t C_buf[TI][J];
  load_A_tile(A, A_buf, t);      // flash LANES walk, TI rows only
  compute_tile(A_buf, B_local, C_buf); // flash compute body
  store_C_tile(C_buf, C, t);    // flash LANES walk, TI rows only
}

